char* reverseVowels(char* s) {
    size_t left = 0, right = strlen(s);
    if (right == 0) return s;
    right--;

    while (left < right) {
        while (left < right && !is_vowel(s[left])) left++;
        while (left < right && !is_vowel(s[right])) right--;
        if (left < right) {
            char tmp = s[left];
            s[left] = s[right];
            s[right] = tmp;
            left++;
            right--;
