using namespace std;

class Solution {
public:
    string reverseVowels(string s) {
        auto isVowel = [](char c) {
            return c=='a'||c=='e'||c=='i'||c=='o'||c=='u'||
                   c=='A'||c=='E'||c=='I'||c=='O'||c=='U';
        };
        int left = 0, right = (int)s.size() - 1;
        while (left < right) {
            while (left < right && !isVowel(s[left])) ++left;
            while (left < right && !isVowel(s[right])) --right;
            if (left < right) {
                swap(s[left], s[right]);
                ++left;
                --right;
            }
        }
        return s;
    }
};

static string parseJsonString(const string& line) {
    size_t i = 0;
    while (i < line.size() && isspace((unsigned char)line[i])) ++i;
    if (i >= line.size() || line[i++] != '[') throw runtime_error("Invalid input");
    while (i < line.size() && isspace((unsigned char)line[i])) ++i;
    if (i >= line.size() || line[i++] != '"') throw runtime_error("Expected string");

    string out;
    while (i < line.size()) {
        char c = line[i++];
        if (c == '"') return out;
        if (c != '\\') {
            out += c;
            continue;
        }
        if (i >= line.size()) throw runtime_error("Invalid escape");
        char e = line[i++];
        switch (e) {
            case '"': out += '"'; break;
            case '\\': out += '\\'; break;
            case '/': out += '/'; break;
            case 'b': out += '\b'; break;
            case 'f': out += '\f'; break;
            case 'n': out += '\n'; break;
            case 'r': out += '\r'; break;
            case 't': out += '\t'; break;
            case 'u': {
                if (i + 4 > line.size()) throw runtime_error("Invalid unicode escape");
                unsigned value = 0;
                for (int k = 0; k < 4; ++k) {
                    char h = line[i++];
                    value <<= 4;
                    if (h >= '0' && h <= '9') value += h - '0';
                    else if (h >= 'a' && h <= 'f') value += h - 'a' + 10;
                    else if (h >= 'A' && h <= 'F') value += h - 'A' + 10;
                    else throw runtime_error("Invalid unicode escape");
                }
                out += (char)value;
                break;
            }
            default: throw runtime_error("Unsupported escape");
        }
    }
    throw runtime_error("Unterminated string");
}

static string jsonEscape(const string& s) {
    string out = "\"";
    const char* hex = "0123456789abcdef";
    for (unsigned char c : s) {
        switch (c) {
            case '"': out += "\\\""; break;
            case '\\': out += "\\\\"; break;
            case '\b': out += "\\b"; break;
            case '\f': out += "\\f"; break;
            case '\n': out += "\\n"; break;
            case '\r': out += "\\r"; break;
            case '\t': out += "\\t"; break;
            default:
                if (c < 0x20) {
                    out += "\\u00";
                    out += hex[c >> 4];
                    out += hex[c & 15];
                } else out += (char)c;
        }
    }
    out += '"';
    return out;
}

